import { useState } from 'react';
import { JxButton, JxInput } from '@jinx-ui/react';

type RegistrationValues = {
  name: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  zip: string;
};

type RegistrationWizardProps = {
  onSubmit: (values: RegistrationValues) => void;
};

const STEPS = ['Контакты', 'Адрес', 'Проверка'] as const;

const EMPTY: RegistrationValues = {
  name: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  zip: '',
};

export default function RegistrationWizard({ onSubmit }: RegistrationWizardProps) {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<RegistrationValues>(EMPTY);

  const set = (key: keyof RegistrationValues) => (next: string) =>
    setValues((prev) => ({ ...prev, [key]: next }));

  const isLast = step === STEPS.length - 1;

  const fieldStyle = {
    display: 'flex',
    flexDirection: 'column' as const,
    gap: 'var(--jx-space-1)',
    marginBottom: 'var(--jx-space-3)',
  };

  const labelStyle = {
    color: 'var(--jx-color-text-muted)',
    fontSize: 'var(--jx-font-size-sm)',
  };

  return (
    <section
      aria-label="Регистрация"
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--jx-space-4)',
        padding: 'var(--jx-space-4)',
        border: '1px solid var(--jx-color-border)',
        borderRadius: 'var(--jx-radius-md)',
        background: 'var(--jx-color-surface)',
        color: 'var(--jx-color-text)',
      }}
    >
      <ol
        style={{
          display: 'flex',
          gap: 'var(--jx-space-2)',
          listStyle: 'none',
          margin: 0,
          padding: 0,
        }}
      >
        {STEPS.map((label, index) => {
          const active = index === step;
          return (
            <li
              key={label}
              aria-current={active ? 'step' : undefined}
              style={{
                flex: 1,
                display: 'flex',
                alignItems: 'center',
                gap: 'var(--jx-space-2)',
                paddingBottom: 'var(--jx-space-2)',
                borderBottom: `2px solid ${
                  index <= step ? 'var(--jx-color-primary)' : 'var(--jx-color-border)'
                }`,
                color: active ? 'var(--jx-color-text)' : 'var(--jx-color-text-muted)',
              }}
            >
              <span
                aria-hidden="true"
                style={{
                  display: 'inline-flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  width: 'var(--jx-space-5)',
                  height: 'var(--jx-space-5)',
                  borderRadius: 'var(--jx-radius-full)',
                  background:
                    index <= step ? 'var(--jx-color-primary)' : 'var(--jx-color-surface-muted)',
                  color:
                    index <= step ? 'var(--jx-color-on-primary)' : 'var(--jx-color-text-muted)',
                  fontSize: 'var(--jx-font-size-sm)',
                }}
              >
                {index + 1}
              </span>
              <span>{label}</span>
            </li>
          );
        })}
      </ol>

      {step === 0 && (
        <div>
          <div style={fieldStyle}>
            <label htmlFor="reg-name" style={labelStyle}>
              Имя
            </label>
            <JxInput id="reg-name" value={values.name} onValueChange={set('name')} />
          </div>
          <div style={fieldStyle}>
            <label htmlFor="reg-email" style={labelStyle}>
              Email
            </label>
            <JxInput
              id="reg-email"
              type="email"
              value={values.email}
              onValueChange={set('email')}
            />
          </div>
          <div style={fieldStyle}>
            <label htmlFor="reg-phone" style={labelStyle}>
              Телефон
            </label>
            <JxInput id="reg-phone" type="tel" value={values.phone} onValueChange={set('phone')} />
          </div>
        </div>
      )}

      {step === 1 && (
        <div>
          <div style={fieldStyle}>
            <label htmlFor="reg-country" style={labelStyle}>
              Страна
            </label>
            <JxInput id="reg-country" value={values.country} onValueChange={set('country')} />
          </div>
          <div style={fieldStyle}>
            <label htmlFor="reg-city" style={labelStyle}>
              Город
            </label>
            <JxInput id="reg-city" value={values.city} onValueChange={set('city')} />
          </div>
          <div style={fieldStyle}>
            <label htmlFor="reg-street" style={labelStyle}>
              Улица и дом
            </label>
            <JxInput id="reg-street" value={values.street} onValueChange={set('street')} />
          </div>
          <div style={fieldStyle}>
            <label htmlFor="reg-zip" style={labelStyle}>
              Индекс
            </label>
            <JxInput id="reg-zip" value={values.zip} onValueChange={set('zip')} />
          </div>
        </div>
      )}

      {step === 2 && (
        <dl style={{ display: 'grid', gap: 'var(--jx-space-2)', margin: 0 }}>
          {(
            [
              ['Имя', values.name],
              ['Email', values.email],
              ['Телефон', values.phone],
              ['Страна', values.country],
              ['Город', values.city],
              ['Улица и дом', values.street],
              ['Индекс', values.zip],
            ] as const
          ).map(([label, value]) => (
            <div
              key={label}
              style={{ display: 'flex', justifyContent: 'space-between', gap: 'var(--jx-space-3)' }}
            >
              <dt style={labelStyle}>{label}</dt>
              <dd style={{ margin: 0 }}>{value || '—'}</dd>
            </div>
          ))}
        </dl>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: 'var(--jx-space-2)' }}>
        <JxButton disabled={step === 0} onClick={() => setStep((prev) => prev - 1)}>
          Назад
        </JxButton>
        <JxButton
          variant="primary"
          onClick={() => (isLast ? onSubmit(values) : setStep((prev) => prev + 1))}
        >
          {isLast ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </section>
  );
}

